import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  if (!token) return res.status(401).json({ error: 'Missing tenant' });
  req.tenantId = token;
  next();
}

// Audit log helper
async function auditLog(action, tenantId, details) {
  const id = crypto.randomUUID();
  await pool.query(
    'INSERT INTO audit_log (id, action, tenant_id, details, created_at) VALUES ($1, $2, $3, $4, NOW())',
    [id, action, tenantId, JSON.stringify(details)]
  );
}

// Search invoices with flexible filtering
app.get('/api/invoices/search', extractTenant, async (req, res) => {
  try {
    const { status, min_amount, max_amount, date_from, date_to, sort_by, order } = req.query;

    let query = `SELECT id, invoice_number, amount, status, due_date, description 
                 FROM invoices WHERE tenant_id = '${req.tenantId}'`;

    if (status) {
      query += ` AND status = '${status}'`;
    }
    if (min_amount) {
      query += ` AND amount >= ${parseFloat(min_amount)}`;
    }
    if (max_amount) {
      query += ` AND amount <= ${parseFloat(max_amount)}`;
    }
    if (date_from) {
      query += ` AND due_date >= '${date_from}'`;
    }
    if (date_to) {
      query += ` AND due_date <= '${date_to}'`;
    }

    // Sort handling
    const allowedSorts = ['amount', 'due_date', 'status', 'invoice_number'];
    if (sort_by && allowedSorts.includes(sort_by)) {
      const direction = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${direction}`;
    } else {
      query += ' ORDER BY due_date DESC';
    }

    query += ' LIMIT 100';

    const result = await pool.query(query);
    await auditLog('invoice_search', req.tenantId, { filters: req.query });
    res.json({ invoices: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get invoice detail
app.get('/api/invoices/:id', extractTenant, async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT * FROM invoices WHERE id = $1 AND tenant_id = $2',
      [req.params.id, req.tenantId]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Not found' });
    }
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Create invoice
app.post('/api/invoices', extractTenant, async (req, res) => {
  try {
    const { amount, description, due_date } = req.body;
    const id = crypto.randomUUID();
    const invoice_number = `INV-${Date.now()}`;
    await pool.query(
      `INSERT INTO invoices (id, tenant_id, invoice_number, amount, description, due_date, status)
       VALUES ($1, $2, $3, $4, $5, $6, 'pending')`,
      [id, req.tenantId, invoice_number, amount, description, due_date]
    );
    await auditLog('invoice_create', req.tenantId, { invoice_id: id });
    res.status(201).json({ id, invoice_number });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(3000, () => console.log('Invoice service running on :3000'));
